import { isBaseMessage } from "@langchain/core/messages";
import * as openAIImports from "@langchain/openai";
import { wrapEvaluator, isInTestContext } from "langsmith/utils/jestlike";
import { traceable } from "langsmith/traceable";
const { 
// @ts-expect-error Shim for older versions of @langchain/openai
_convertMessagesToOpenAIParams, convertMessagesToCompletionsMessageParams, } = openAIImports;
function _convertMessagesShim(message) {
    if (typeof _convertMessagesToOpenAIParams === "function") {
        return _convertMessagesToOpenAIParams([
            message,
        ])[0];
    }
    return convertMessagesToCompletionsMessageParams({
        messages: [message],
    })[0];
}
export const _convertToOpenAIMessage = (message) => {
    if (isBaseMessage(message)) {
        const converted = _convertMessagesShim(message);
        if (message.id && !converted.id) {
            converted.id = message.id;
        }
        return converted;
    }
    else {
        return message;
    }
};
export const _normalizeToOpenAIMessagesList = (messages) => {
    let messagesList;
    if (!Array.isArray(messages)) {
        if ("messages" in messages && Array.isArray(messages.messages)) {
            messagesList = messages.messages;
        }
        else if ("content" in messages && "role" in messages) {
            messagesList = [messages];
        }
        else {
            throw new Error(`If passing messages as an object, it must contain a "messages" key`);
        }
    }
    else {
        messagesList = messages;
    }
    return messagesList.map(_convertToOpenAIMessage);
};
export const processScore = (_, value) => {
    if (typeof value === "object") {
        if (value != null && "score" in value) {
            return [
                value.score,
                "reasoning" in value && typeof value.reasoning === "string"
                    ? value.reasoning
                    : undefined,
                value.metadata,
                value.sourceRunId,
            ];
        }
        else {
            throw new Error(`Expected a dictionary with a "score" key, but got "${JSON.stringify(value, null, 2)}"`);
        }
    }
    return [value];
};
export async function _runEvaluator(runName, scorer, feedbackKey, extra, ls_framework) {
    return _runEvaluatorUntyped(runName, scorer, feedbackKey, extra, ls_framework, false);
}
export async function _runEvaluatorUntyped(runName, scorer, feedbackKey, extra, ls_framework, returnRawOutputs) {
    const runScorer = async (params) => {
        let score = await scorer(params);
        if (returnRawOutputs) {
            return score;
        }
        let reasoning;
        if (!Array.isArray(score) && typeof score === "object") {
            const results = [];
            for (const [key, value] of Object.entries(score)) {
                const [keyScore, reasoning, metadata, sourceRunId] = processScore(key, 
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                value);
                const result = {
                    key,
                    score: keyScore,
                    comment: reasoning,
                    metadata,
                };
                if (sourceRunId !== undefined && typeof sourceRunId === "string") {
                    result.sourceRunId = sourceRunId;
                }
                results.push(result);
            }
            return results;
        }
        else {
            let metadata;
            if (Array.isArray(score)) {
                metadata = score[2];
                reasoning = score[1];
                score = score[0];
            }
            return {
                key: feedbackKey,
                score,
                comment: reasoning,
                metadata,
            };
        }
    };
    if (isInTestContext()) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const res = await wrapEvaluator(runScorer)(extra ?? {}, {
            name: runName,
            metadata: {
                __ls_framework: ls_framework ?? "openevals",
                __ls_evaluator: runName,
                __ls_language: "js",
            },
        });
        if (returnRawOutputs) {
            // TODO: Fix LangSmith SDK types
            const rawResults = res;
            return rawResults;
        }
        return res;
    }
    else {
        const traceableRunScorer = traceable(runScorer, {
            name: runName,
            metadata: {
                __ls_framework: ls_framework ?? "openevals",
                __ls_evaluator: runName,
                __ls_language: "js",
            },
        });
        const res = await traceableRunScorer(extra ?? {});
        return res;
    }
}
export function _normalizeOutputsAsString(outputs) {
    if (typeof outputs === "string") {
        return outputs;
    }
    else if (outputs !== null && typeof outputs === "object") {
        if ("content" in outputs) {
            return outputs.content;
        }
        else if ("messages" in outputs &&
            Array.isArray(outputs.messages) &&
            outputs.messages.length > 0) {
            return outputs.messages[outputs.messages.length - 1].content;
        }
        else {
            throw new Error(`Expected a string, dictionary with a 'content' key or a 'messages' key with a list of messages, but got ${JSON.stringify(outputs, null, 2)}`);
        }
    }
    else {
        throw new Error(`Expected string or object, got ${typeof outputs}`);
    }
}
